func (m *TopSystemModel) BuildRN() string {
	rn := "pod-{podId}/node-{id}/sys"
	rn = strings.ReplaceAll(rn, "{id}", m.TopSystemID.ValueString())
	rn = strings.ReplaceAll(rn, "{podId}", m.PodId.ValueString())
	return rn
}

