func (m *TopSystemModel) BuildPayloadObject(
	ctx context.Context,
	priorState *TopSystemModel,
	nested bool,
	defaultAnnotation string,
) (map[string]any, diag.Diagnostics) {
	var diagnostics diag.Diagnostics
	attributes := map[string]any{}
	children := make([]map[string]any, 0)

	modelHelpers.AddPayloadStringAttribute(ctx, &diagnostics, attributes, "id", m.TopSystemID)
	modelHelpers.AddPayloadStringAttribute(ctx, &diagnostics, attributes, "podId", m.PodId)

	return modelHelpers.NewPayloadObject(
		ctx,
		&diagnostics,
		attributes,
		children,
		nested,
	), diagnostics
}

type TopSystemRootModel struct {
	TopSystemModel

	ID types.String `tfsdk:"id"`
}

func NewTopSystemRootModelNull() TopSystemRootModel {
	return TopSystemRootModel{
		TopSystemModel: NewTopSystemModelNull(),
		ID:             types.StringNull(),
	}
}

func (*TopSystemRootModel) SupportedSubtreeClasses(apicVersion string) []string {
	return supportedSubtreeClasses(apicVersion, []string{})
}

func (m *TopSystemRootModel) BuildDN() string {
	return fmt.Sprintf("topology/%s", m.BuildRN())
}

func (m *TopSystemRootModel) SetIDFromDN(dn string) {
	m.ID = types.StringValue(dn)
}

func (m *TopSystemRootModel) SetFromResponse(
	ctx context.Context,
	response *container.Container,
) (bool, diag.Diagnostics) {
	fallbackModel := m.TopSystemModel
	model, dn, diagnostics := TopSystemModelFromResponse(ctx, response, &fallbackModel)
	found := model != nil
	if diagnostics.HasError() || !found {
		return found, diagnostics
	}

	m.TopSystemModel = *model
	m.ID = types.StringValue(dn)
	return true, diagnostics
}
